package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "TripleDES", "RC2", "RC4", "Blowfish", "MD4", "MD5", "SHA1", "SHA-1", "RIPEMD", "WHIRLPOOL", "NULL"}

weak_tls_versions := {"TLS_1_0", "TLS_1_1", "TLSv1", "TLSv1_1", "SSLv2", "SSLv3", "SSL2", "SSL3", "PCT1"}

weak_cipher_indicators := {"DES-CBC", "RC4-MD5", "anon", "EXPORT"}

algorithm_attr_names := {"encryption_algorithm", "cipher", "block_cipher", "stream_cipher", "hash_algorithm", "digest", "checksum_algorithm", "key_exchange", "key_agreement", "key_derivation", "mac_algorithm", "hmac_algorithm", "signature_algorithm", "signing_algorithm", "sse_algorithm", "tde_key_algorithm", "algorithm", "public_key_algorithm", "jwt_signature", "password_hash", "key_derivation_function"}

tls_version_attr_names := {"min_tls_version", "security_protocol", "tls_version", "min_version", "version"}

policy_attr_names := {"ssl_policy", "tls_policy", "security_policy", "policy", "ipsec_policy", "ike_policy"}

enhancement_attr_names := {"enabled", "enable_legacy", "enforce_ssl", "encryption", "insecure_skip_verify", "export_ciphers_enabled", "weak_ciphers_allowed"}

contains_weak_algorithm(value) {
    value.ir_type == "String"
    upper_value := upper(value.value)
    weak_algorithms[_] == upper_value
} else {
    value.ir_type == "String"
    regex.match("(?i).*(DES|RC[24]|MD[45]|SHA-?1|RIPEMD|WHIRLPOOL|NULL).*", value.value)
}

contains_weak_tls_version(value) {
    value.ir_type == "String"
    upper_value := upper(value.value)
    weak_tls_versions[_] == upper_value
} else {
    value.ir_type == "String"
    regex.match("(?i).*(TLS_?1[._]?[01]|SSL[23]?|PCT1).*", value.value)
}

contains_weak_cipher_indicator(value) {
    value.ir_type == "String"
    regex.match("(?i).*(DES-CBC|RC4-MD5|anon|EXPORT|NULL).*", value.value)
}

has_legacy_policy_name(value) {
    value.ir_type == "String"
    regex.match("(?i).*(Legacy|2015|2016|FS-2018-06).*", value.value)
}

is_weak_enhancement_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
}

is_encryption_none(value) {
    value.ir_type == "String"
    upper(value.value) == "NONE"
}

check_nested_values(node) {
    node.ir_type == "Hash"
    some val in node.value
    check_nested_values(val.value)
} else {
    node.ir_type == "Array"
    some elem in node.value
    check_nested_values(elem)
} else {
    contains_weak_algorithm(node)
} else {
    contains_weak_tls_version(node)
} else {
    contains_weak_cipher_indicator(node)
} else {
    has_legacy_policy_name(node)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in algorithm_attr_names
    check_nested_values(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a broken or risky cryptographic algorithm - Weak or deprecated cryptographic algorithms should not be used. (CWE-327)"
    }
}

